// Prepare handoff response
const input = $input.item.json;

const handoffMessage = `Merci pour votre message. Un membre de notre equipe va prendre le relais et vous repondra dans les plus brefs delais.`;

return {
  json: {
    reply_text: handoffMessage,
    action: 'handoff',
    handoff: true,
    handoff_reason: input.handoff_reason,
    stage: input.new_stage,
    intent: input.intent,
    source: input.source,
    conversation_id: input.conversation_id,
    sender_id: input.sender_id,
    message_id: input.message_id
  }
};

// Prepare booking response
const input = $input.item.json;

const bookingMessage = `Super ! Je serais ravi de vous aider a reserver. Pour finaliser votre rendez-vous, j'aurais besoin de quelques informations.`;

return {
  json: {
    reply_text: bookingMessage,
    action: 'book',
    handoff: false,
    stage: 'booking',
    intent: input.intent,
    entities: input.entities,
    source: input.source,
    conversation_id: input.conversation_id,
    sender_id: input.sender_id,
    message_id: input.message_id
  }
};

// Prepare auto-reply response
const input = $input.item.json;
const replyText = $('Generate Reply (OpenAI)').item.json.message.content;

// Choose variant based on time and randomness for human-like feel
const variants = [
  replyText,
  replyText.replace(/!/g, '.'),
  replyText + ' 😊'.replace(/😊/g, '') // Remove emoji by default
];

// Simple variant selection (first one for consistency)
const selectedReply = variants[0];

return {
  json: {
    reply_text: selectedReply,
    action: 'send',
    handoff: false,
    stage: input.new_stage,
    intent: input.intent,
    source: input.source,
    conversation_id: input.conversation_id,
    sender_id: input.sender_id,
    message_id: input.message_id
  }
};
